// AndConstraintConstraint is the term type of the variadic operator `AndConstraint(...)` of sort Constraint
// (Java's abstract class AndConstraint): a maximally-shared cons cell (Java's
// ConsAndConstraint: a head and a tail) or the empty list (Java's EmptyAndConstraint).
type AndConstraintConstraint struct {
	head  Constraint
	tail  Constraint
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*AndConstraintConstraint) isConstraint() {}

func (t *AndConstraintConstraint) Hash() uint32 { return t.hash }

func (t *AndConstraintConstraint) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*AndConstraintConstraint)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *AndConstraintConstraint) Duplicate() sharedobjects.Term {
	return &AndConstraintConstraint{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
func (t *AndConstraintConstraint) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *AndConstraintConstraint) ChildCount() int { return len(t.elements()) }

func (t *AndConstraintConstraint) ChildAt(i int) any { return t.elements()[i] }

func (t *AndConstraintConstraint) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *AndConstraintConstraint) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: AndConstraintFromArray(children).
func (t *AndConstraintConstraint) SetChildren(children []any) any {
	args := make([]Constraint, len(children))
	for i, c := range children {
		args[i] = c.(Constraint)
	}
	return MakeAndConstraint(args...)
}

func (t *AndConstraintConstraint) String() string {
	var b strings.Builder
	b.WriteString("AndConstraint(")
	var cur Constraint = t
	for {
		c, ok := cur.(*AndConstraintConstraint)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsAndConstraint is Java Gom's ConsAndConstraint.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsAndConstraint(head Constraint, tail Constraint) Constraint {
	proto := &AndConstraintConstraint{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsAndConstraint"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*AndConstraintConstraint)
}

// realMakeEmptyAndConstraint is Java Gom's EmptyAndConstraint.realMake: the shared empty list,
// without hook.
func realMakeEmptyAndConstraint() Constraint {
	proto := &AndConstraintConstraint{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyAndConstraint"), nil)}
	return factory.Build(proto).(*AndConstraintConstraint)
}

// RawAndConstraint builds the AndConstraint list holding exactly args, without construction
// hook.
func RawAndConstraint(args ...Constraint) Constraint {
	l := realMakeEmptyAndConstraint()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsAndConstraint(args[i], l)
	}
	return l
}

// EmptyAndConstraint is Java Gom's EmptyAndConstraint.make(): the empty AndConstraint list, after the
// construction hooks.
func EmptyAndConstraint() Constraint {
	// AU: the empty list is the neutral element
	return MakeTrueConstraint()
}

// ConsAndConstraint is Java Gom's ConsAndConstraint.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "AU" first).
func ConsAndConstraint(head Constraint, tail Constraint) Constraint {
	// AU: neutral element
	if head == MakeTrueConstraint() {
		return tail
	}
	if tail == MakeTrueConstraint() {
		return head
	}
	// AU: flattening, the empty list is neutral
	if head.IsEmptyAndConstraint() {
		return tail
	}
	if tail.IsEmptyAndConstraint() {
		return head
	}
	if head.IsConsAndConstraint() {
		return ConsAndConstraint(head.GetHeadAndConstraint(), ConsAndConstraint(head.GetTailAndConstraint(), tail))
	}
	return RealMakeConsAndConstraint(head, tail)
}

// MakeAndConstraint builds the list of args as Tom's `AndConstraint(args…)` does: from EmptyAndConstraint,
// by ConsAndConstraint, through the construction hooks (Java's AndConstraint.fromArray).
func MakeAndConstraint(args ...Constraint) Constraint {
	var l Constraint = EmptyAndConstraint()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsAndConstraint(args[i], l)
	}
	return l
}

// AndConstraintFromArray is Java Gom's AndConstraint.fromArray(array).
func AndConstraintFromArray(array []Constraint) Constraint { return MakeAndConstraint(array...) }

// IsAndConstraint is the `Is_AndConstraint` predicate strategy: succeeds (returns subject
