// Length is Java's length(): the number of elements of the list (a
// tail that is not a AndConstraint list counts as one element).
func (t *AndConstraintConstraint) Length() int {
	res := 0
	var tl Constraint = t
	for {
		c, ok := tl.(*AndConstraintConstraint)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*AndConstraintConstraint); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a AndConstraint list.
func (t *AndConstraintConstraint) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur Constraint = t
	for {
		c, ok := cur.(*AndConstraintConstraint)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*AndConstraintConstraint); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsAndConstraint
// (through the hooks).
func (t *AndConstraintConstraint) Reverse() Constraint {
	if t.empty {
		return t
	}
	var cur Constraint = t
	var rev Constraint = EmptyAndConstraint()
	for {
		c, ok := cur.(*AndConstraintConstraint)
		if !ok || c.empty {
			break
		}
		rev = ConsAndConstraint(c.head, rev)
		cur = c.tail
	}
	if c, ok := cur.(*AndConstraintConstraint); !ok || !c.empty {
		rev = ConsAndConstraint(cur, rev)
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsAndConstraint (through the hooks).
func (t *AndConstraintConstraint) Append(element Constraint) Constraint {
	var heads []Constraint
	var cur Constraint = t
	for {
		c, ok := cur.(*AndConstraintConstraint)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res Constraint
	if c, ok := cur.(*AndConstraintConstraint); ok && c.empty {
		res = ConsAndConstraint(element, cur)
	} else {
		res = ConsAndConstraint(cur, element)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsAndConstraint(heads[i], res)
	}
	return res
}

func (t *AndConstraintConstraint) CompareTo(o any) int {
	for {
		ao := o.(Constraint)
		if ao == Constraint(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*AndConstraintConstraint)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*AndConstraintConstraint)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *AndConstraintConstraint) CompareToLPO(o any) int {
	for {
		ao := o.(Constraint)
		if ao == Constraint(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*AndConstraintConstraint)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*AndConstraintConstraint)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *AndConstraintConstraint) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Constraint
	var cur Constraint = t
	for {
		c, ok := cur.(*AndConstraintConstraint)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*AndConstraintConstraint); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermAndConstraintConstraint is Java Gom's AndConstraint.fromTerm: an application of AndConstraint, or a
// list (of ToATerm), of convertible elements.
func fromTermAndConstraintConstraint(trm aterm.ATerm, conv aterm.ATermConverter) (res Constraint, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "AndConstraint" {
		elems := make([]Constraint, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = ConstraintFromTermConv(a, conv)
		}
		return MakeAndConstraint(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a AndConstraint (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Constraint
		for !list.IsEmpty() {
			elems = append(elems, ConstraintFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeAndConstraint(elems...), true
	}
	return nil, false
}

// OrConstraintConstraint is the term type of the variadic operator `OrConstraint(...)` of sort Constraint
// (Java's abstract class OrConstraint): a maximally-shared cons cell (Java's
// ConsOrConstraint: a head and a tail) or the empty list (Java's EmptyOrConstraint).
type OrConstraintConstraint struct {
	head  Constraint
	tail  Constraint
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*OrConstraintConstraint) isConstraint() {}

func (t *OrConstraintConstraint) Hash() uint32 { return t.hash }

func (t *OrConstraintConstraint) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*OrConstraintConstraint)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *OrConstraintConstraint) Duplicate() sharedobjects.Term {
	return &OrConstraintConstraint{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
func (t *OrConstraintConstraint) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *OrConstraintConstraint) ChildCount() int { return len(t.elements()) }

func (t *OrConstraintConstraint) ChildAt(i int) any { return t.elements()[i] }

func (t *OrConstraintConstraint) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *OrConstraintConstraint) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: OrConstraintFromArray(children).
func (t *OrConstraintConstraint) SetChildren(children []any) any {
	args := make([]Constraint, len(children))
	for i, c := range children {
		args[i] = c.(Constraint)
	}
	return MakeOrConstraint(args...)
}

func (t *OrConstraintConstraint) String() string {
	var b strings.Builder
	b.WriteString("OrConstraint(")
	var cur Constraint = t
	for {
		c, ok := cur.(*OrConstraintConstraint)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsOrConstraint is Java Gom's ConsOrConstraint.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsOrConstraint(head Constraint, tail Constraint) Constraint {
	proto := &OrConstraintConstraint{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsOrConstraint"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*OrConstraintConstraint)
}

// realMakeEmptyOrConstraint is Java Gom's EmptyOrConstraint.realMake: the shared empty list,
// without hook.
func realMakeEmptyOrConstraint() Constraint {
	proto := &OrConstraintConstraint{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyOrConstraint"), nil)}
	return factory.Build(proto).(*OrConstraintConstraint)
}

// RawOrConstraint builds the OrConstraint list holding exactly args, without construction
// hook.
func RawOrConstraint(args ...Constraint) Constraint {
	l := realMakeEmptyOrConstraint()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsOrConstraint(args[i], l)
	}
	return l
}

// EmptyOrConstraint is Java Gom's EmptyOrConstraint.make(): the empty OrConstraint list, after the
// construction hooks.
func EmptyOrConstraint() Constraint {
	// AU: the empty list is the neutral element
	return MakeFalseConstraint()
}

// ConsOrConstraint is Java Gom's ConsOrConstraint.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "AU" first).
func ConsOrConstraint(head Constraint, tail Constraint) Constraint {
	// AU: neutral element
	if head == MakeFalseConstraint() {
		return tail
	}
	if tail == MakeFalseConstraint() {
		return head
	}
	// AU: flattening, the empty list is neutral
	if head.IsEmptyOrConstraint() {
		return tail
	}
	if tail.IsEmptyOrConstraint() {
		return head
	}
	if head.IsConsOrConstraint() {
		return ConsOrConstraint(head.GetHeadOrConstraint(), ConsOrConstraint(head.GetTailOrConstraint(), tail))
	}
	return RealMakeConsOrConstraint(head, tail)
}

// MakeOrConstraint builds the list of args as Tom's `OrConstraint(args…)` does: from EmptyOrConstraint,
// by ConsOrConstraint, through the construction hooks (Java's OrConstraint.fromArray).
func MakeOrConstraint(args ...Constraint) Constraint {
	var l Constraint = EmptyOrConstraint()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsOrConstraint(args[i], l)
	}
	return l
}

// OrConstraintFromArray is Java Gom's OrConstraint.fromArray(array).
func OrConstraintFromArray(array []Constraint) Constraint { return MakeOrConstraint(array...) }

