func (*OrConstraintDisjunctionConstraint) isConstraint() {}

func (t *OrConstraintDisjunctionConstraint) Hash() uint32 { return t.hash }

func (t *OrConstraintDisjunctionConstraint) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*OrConstraintDisjunctionConstraint)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

