func (t *OrConstraintDisjunctionConstraint) SetChildren(children []any) any {
	args := make([]Constraint, len(children))
	for i, c := range children {
		args[i] = c.(Constraint)
	}
	return MakeOrConstraintDisjunction(args...)
}

func (t *OrConstraintDisjunctionConstraint) String() string {
	var b strings.Builder
	b.WriteString("OrConstraintDisjunction(")
	var cur Constraint = t
	for {
		c, ok := cur.(*OrConstraintDisjunctionConstraint)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsOrConstraintDisjunction is Java Gom's ConsOrConstraintDisjunction.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsOrConstraintDisjunction(head Constraint, tail Constraint) Constraint {
	proto := &OrConstraintDisjunctionConstraint{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsOrConstraintDisjunction"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*OrConstraintDisjunctionConstraint)
}

// realMakeEmptyOrConstraintDisjunction is Java Gom's EmptyOrConstraintDisjunction.realMake: the shared empty list,
// without hook.
func realMakeEmptyOrConstraintDisjunction() Constraint {
	proto := &OrConstraintDisjunctionConstraint{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyOrConstraintDisjunction"), nil)}
	return factory.Build(proto).(*OrConstraintDisjunctionConstraint)
}

// RawOrConstraintDisjunction builds the OrConstraintDisjunction list holding exactly args, without construction
// hook.
func RawOrConstraintDisjunction(args ...Constraint) Constraint {
	l := realMakeEmptyOrConstraintDisjunction()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsOrConstraintDisjunction(args[i], l)
	}
	return l
}

// EmptyOrConstraintDisjunction is Java Gom's EmptyOrConstraintDisjunction.make(): the empty OrConstraintDisjunction list, after the
// construction hooks.
func EmptyOrConstraintDisjunction() Constraint {
	return realMakeEmptyOrConstraintDisjunction()
}

// ConsOrConstraintDisjunction is Java Gom's ConsOrConstraintDisjunction.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "AU" first).
func ConsOrConstraintDisjunction(head Constraint, tail Constraint) Constraint {
	// AU: flattening, the empty list is neutral
	if head.IsEmptyOrConstraintDisjunction() {
		return tail
	}
	if tail.IsEmptyOrConstraintDisjunction() {
		return head
	}
	if head.IsConsOrConstraintDisjunction() {
		return ConsOrConstraintDisjunction(head.GetHeadOrConstraintDisjunction(), ConsOrConstraintDisjunction(head.GetTailOrConstraintDisjunction(), tail))
	}
	return RealMakeConsOrConstraintDisjunction(head, tail)
}

// MakeOrConstraintDisjunction builds the list of args as Tom's `OrConstraintDisjunction(args…)` does: from EmptyOrConstraintDisjunction,
// by ConsOrConstraintDisjunction, through the construction hooks (Java's OrConstraintDisjunction.fromArray).
func MakeOrConstraintDisjunction(args ...Constraint) Constraint {
	var l Constraint = EmptyOrConstraintDisjunction()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsOrConstraintDisjunction(args[i], l)
	}
	return l
}

// OrConstraintDisjunctionFromArray is Java Gom's OrConstraintDisjunction.fromArray(array).
func OrConstraintDisjunctionFromArray(array []Constraint) Constraint {
	return MakeOrConstraintDisjunction(array...)
}

