// NumericConstraintTypeFromTermConv is Java Gom's NumericConstraintType.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func NumericConstraintTypeFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) NumericConstraintType {
	converted := conv.Convert(trm)
	var results []NumericConstraintType
	if r, ok := fromTermNumLessThanNumericConstraintType(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermNumLessOrEqualThanNumericConstraintType(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermNumGreaterThanNumericConstraintType(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermNumGreaterOrEqualThanNumericConstraintType(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermNumDifferentNumericConstraintType(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermNumEqualNumericConstraintType(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a NumericConstraintType", trm), IllegalArgument: true})
	}
	return results[0]
}

