func (t *ConcConstraintConstraintList) IsEmptyconcConstraint() bool { return t.empty }

func (t *ConcConstraintConstraintList) GetHeadconcConstraint() Constraint {
	if t.empty {
		panic(&aterm.GomError{Msg: "This ConstraintList has no HeadconcConstraint"})
	}
	return t.head
}
func (t *ConcConstraintConstraintList) GetTailconcConstraint() ConstraintList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This ConstraintList has no TailconcConstraint"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concConstraint list counts as one element).
func (t *ConcConstraintConstraintList) Length() int {
	res := 0
	var tl ConstraintList = t
	for {
		c, ok := tl.(*ConcConstraintConstraintList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcConstraintConstraintList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concConstraint list.
func (t *ConcConstraintConstraintList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur ConstraintList = t
	for {
		c, ok := cur.(*ConcConstraintConstraintList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcConstraintConstraintList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcConstraint
// (through the hooks).
func (t *ConcConstraintConstraintList) Reverse() ConstraintList {
	if t.empty {
		return t
	}
	var cur ConstraintList = t
	var rev ConstraintList = EmptyConcConstraint()
	for {
		c, ok := cur.(*ConcConstraintConstraintList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcConstraint(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcConstraint (through the hooks).
func (t *ConcConstraintConstraintList) Append(element Constraint) ConstraintList {
	var heads []Constraint
	var cur ConstraintList = t
	for {
		c, ok := cur.(*ConcConstraintConstraintList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res ConstraintList
	if c, ok := cur.(*ConcConstraintConstraintList); ok && c.empty {
		res = ConsConcConstraint(element, cur)
	} else {
		res = ConsConcConstraint(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcConstraint(heads[i], res)
	}
	return res
}

func (t *ConcConstraintConstraintList) CompareTo(o any) int {
	for {
		ao := o.(ConstraintList)
		if ao == ConstraintList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcConstraintConstraintList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcConstraintConstraintList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcConstraintConstraintList) CompareToLPO(o any) int {
	for {
		ao := o.(ConstraintList)
		if ao == ConstraintList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcConstraintConstraintList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcConstraintConstraintList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcConstraintConstraintList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Constraint
	var cur ConstraintList = t
	for {
		c, ok := cur.(*ConcConstraintConstraintList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcConstraintConstraintList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcConstraintConstraintList is Java Gom's concConstraint.fromTerm: an application of concConstraint, or a
// list (of ToATerm), of convertible elements.
func fromTermConcConstraintConstraintList(trm aterm.ATerm, conv aterm.ATermConverter) (res ConstraintList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concConstraint" {
		elems := make([]Constraint, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = ConstraintFromTermConv(a, conv)
		}
		return MakeConcConstraint(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concConstraint (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Constraint
		for !list.IsEmpty() {
			elems = append(elems, ConstraintFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcConstraint(elems...), true
	}
	return nil, false
}
